function parseDice(text) {
  const m = text.match(/^(\d*)d(\d+)([+-]\d+)?$/);
  if (!m) return null;
  return {
    count: m[1] ? Number(m[1]) : 1,
    sides: Number(m[2]),
    bonus: m[3] ? Number(m[3]) : 0
  };
}

