stages.s:
function parseLog(log) {
  const out = [];
  for (const line of log.split(/\n/)) {
    const m = line.match(/^\[(?<time>\d{2}:\d{2})\] (?<level>INFO|WARN|ERROR) (?<msg>.+)$/);
    if (m) out.push({ time: m.groups.time, level: m.groups.level, msg: m.groups.msg });
  }
  return out;
}

